  for (const flightId of matched) {
    await db
      .update(flights)
      .set({
        aircraftRegistration: registration,
        aircraftType: aircraftType,
        updatedAt: new Date(),
      })
      .where(
        and(
          eq(flights.id, flightId),
          isNull(flights.aircraftRegistration),
        ),
      );
  }

